import { randomBytes } from 'node:crypto';
import type { Readable } from 'node:stream';
import type { AppConfig } from '../../config/env.js';
import { AgentDocumentStorage } from './agentStorage.js';
import { DisabledDocumentStorage } from './disabledStorage.js';
import { LocalDocumentStorage } from './localStorage.js';

/**
 * Private document storage (bill photographs and PDFs).
 *
 * Business code depends only on this interface, never on a provider. Rules for every adapter:
 *  - objects are PRIVATE: no public URLs, no static hosting of the storage location;
 *  - keys are generated by the server (`newStorageKey()`); user-supplied names are never paths;
 *  - `put` must be all-or-nothing: after a failed `put` no readable object exists under the key.
 *
 * Implemented: `local` (a directory on the API server's disk), `agent` (the authenticated storage
 * agent on the owner's desktop, reached through Cloudflare Tunnel) and `disabled` (attachments are
 * postponed: stores nothing, see docs/bill-attachments-postponed.md). A private object-storage adapter
 * (S3-compatible, Azure Blob, GCS, ...) can be added by implementing this interface and wiring it
 * in `createDocumentStorage`; see docs/architecture.md → "Bill documents" for the planned settings.
 */
export interface DocumentStorage {
  readonly driver: string;
  /** Stores bytes under a NEW key. Fails if the key already exists. */
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  /** Opens an object for streaming. Throws StorageObjectMissing when it does not exist. */
  open(key: string): Promise<{ stream: Readable; sizeBytes: number }>;
  /** Deletes an object. Deleting a missing object is not an error. */
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
  /**
   * Re-reads a stored object AT the storage and returns its size and SHA-256: proof that the bytes
   * are really in permanent storage (used before a "permanent" upload is recorded). Throws
   * StorageObjectMissing when it does not exist, StorageUnavailable when the storage cannot answer.
   */
  digest(key: string): Promise<{ sizeBytes: number; sha256Hex: string }>;
  /** Can the storage be reached right now? Never throws. */
  isAvailable(): Promise<boolean>;
  /** Every stored object (for reconciliation). Entries whose name is not a valid key are reported too. */
  list(): AsyncIterable<StoredObject>;
  /**
   * A short-lived, pre-authorised URL for providers that support one (e.g. signed object-storage
   * URLs). Returns null when the provider has none; the API then streams the file itself after
   * its own authorisation checks. Callers must authorise the user BEFORE asking for a URL.
   */
  createAccessUrl(key: string, options: { expiresInSeconds: number; fileName: string; download: boolean }): Promise<string | null>;
}

export interface StoredObject {
  /** The storage key, or the raw relative name for stray entries that are not valid keys. */
  key: string;
  validKey: boolean;
  sizeBytes: number;
  modifiedAt: Date;
}

export class StorageObjectMissing extends Error {
  constructor(key: string) {
    super(`Stored object not found: ${key}`);
    this.name = 'StorageObjectMissing';
  }
}

/**
 * The storage provider cannot be reached right now (e.g. the desktop is off). Uploads are then
 * queued in PostgreSQL (see documentQueue.ts) instead of failing; reads report 503.
 */
export class StorageUnavailable extends Error {
  constructor(message = 'Document storage is unavailable') {
    super(message);
    this.name = 'StorageUnavailable';
  }
}

/**
 * Bill-attachment storage is POSTPONED (DOCUMENT_STORAGE_DRIVER=disabled; see
 * docs/bill-attachments-postponed.md). It is a StorageUnavailable so that read paths that already
 * cope with an unreachable storage degrade to a clear error. Uploads must NOT be treated as "storage
 * offline" (that path parks the bytes in PostgreSQL): they are refused up front instead.
 */
export class StorageDisabled extends StorageUnavailable {
  constructor() {
    super('Bill attachment storage is disabled (DOCUMENT_STORAGE_DRIVER=disabled)');
    this.name = 'StorageDisabled';
  }
}

/**
 * The agent answered 401/403: the request signature was refused. Almost always configuration
 * (DOCUMENT_STORAGE_AGENT_SECRET differs from AGENT_SECRET, or the desktop clock is off by more than
 * 5 minutes). It is still a StorageUnavailable, so uploads are queued and nothing is lost.
 */
export class StorageAgentRejected extends StorageUnavailable {
  constructor(readonly status: number) {
    super(
      `Document storage agent rejected the request (HTTP ${status}): check that DOCUMENT_STORAGE_AGENT_SECRET equals the agent's AGENT_SECRET and that the desktop clock is correct`,
    );
    this.name = 'StorageAgentRejected';
  }
}

/** Lower-case alphanumeric segments separated by "/" (no dots, so no traversal is expressible). */
export const STORAGE_KEY_PATTERN = /^[a-z0-9]+(\/[a-z0-9]+)*$/;

export function isValidStorageKey(key: string): boolean {
  return key.length <= 200 && STORAGE_KEY_PATTERN.test(key);
}

/** New random key, e.g. "3f/9c1e…" (128 random bits; the 2-character prefix spreads files over folders). */
export function newStorageKey(): string {
  const id = randomBytes(16).toString('hex');
  return `${id.slice(0, 2)}/${id}`;
}

export function createDocumentStorage(
  config: AppConfig['documentStorage'],
  options: { onAgentRejected?: (details: { status: number; method: string }) => void } = {},
): DocumentStorage {
  switch (config.driver) {
    case 'disabled':
      return new DisabledDocumentStorage();
    case 'local':
      return new LocalDocumentStorage(config.directory);
    case 'agent':
      return new AgentDocumentStorage(config.url, config.secret, { ...(options.onAgentRejected ? { onRejected: options.onAgentRejected } : {}) });
  }
}
